const PROJECTS = [
  { project_id: '964775386a3ce03ecca883.03770715', name: 'Realchecker (FE)', role: 'source' },
  { project_id: '852017176a3ce11141ecd5.60405885', name: 'Realchecker (BE)', role: 'source' },
  { project_id: '14240418673f52ae29a007.74392007', name: 'Mobitrace', role: 'target' },
  { project_id: '9274956467e3e224807498.79791832', name: 'Mobitrace - backend/emails', role: 'target' },
  { project_id: '901014606819db6d0bc999.26230201', name: 'Mobitrace - html/legal pages', role: 'target' }
];
const out = [];
for (const p of PROJECTS) { out.push({ json: p }); }
return out;

const metas = $('Build Key Requests').all();
const res = $input.all();
const statuses = {};
const failed = [];
const srcRows = [];
const tgtRows = [];
const perProject = {};
let sampleTrans = null;

function kname(k) {
  if (k.key_name && typeof k.key_name === 'object') { return k.key_name.web || k.key_name.other || k.key_name.ios || k.key_name.android; }
  return k.key_name;
}
function isoOf(t) { return String(t.language_iso || '').toLowerCase(); }

for (let i = 0; i < res.length; i++) {
  const meta = metas[i] ? metas[i].json : {};
  const r = res[i].json || {};
  statuses[String(r.statusCode)] = (statuses[String(r.statusCode)] || 0) + 1;
  if (r.statusCode !== 200) { failed.push(meta.project_name + ' -> ' + r.statusCode); continue; }
  const keys = (r.body && r.body.keys) ? r.body.keys : [];
  perProject[meta.project_name] = (perProject[meta.project_name] || 0) + keys.length;
  for (const k of keys) {
    if (sampleTrans === null && (k.translations || []).length) { sampleTrans = JSON.stringify(k.translations[0]).slice(0, 600); }
    let en = null;
    let el = null;
    let elReviewed = null;
    let elBy = null;
    let elAt = null;
    let elId = null;
    for (const t of (k.translations || [])) {
      const iso = isoOf(t);
      const lid = t.language_id === undefined ? null : t.language_id;
      if (iso === 'en' || lid === meta.en_id) { en = t.translation; }
      if (iso === 'el' || (meta.el_id !== null && lid === meta.el_id)) { el = t.translation; elReviewed = t.is_reviewed; elBy = t.modified_by_email; elAt = t.modified_at; elId = t.translation_id; }
    }
    const row = { project_id: meta.project_id, project_name: meta.project_name, key_id: k.key_id, key_name: kname(k), is_archived: k.is_archived, platforms: (k.platforms || []).join('|'), is_plural: k.is_plural, en: en, el: el, el_reviewed: elReviewed, el_modified_by_email: elBy, el_modified_at: elAt, el_translation_id: elId };
    if (meta.role === 'source') { srcRows.push(row); } else { tgtRows.push(row); }
  }
}

function norm(s) {
  if (typeof s !== 'string') { return ''; }
  return s.replace(/\s+/g, ' ').trim();
}

const exactIdx = {};
const normIdx = {};
for (const t of tgtRows) {
  if (typeof t.en !== 'string' || t.en === '') { continue; }
  const ek = 'E' + t.en;
  if (!exactIdx[ek]) { exactIdx[ek] = []; }
  exactIdx[ek].push(t);
  const nk = 'N' + norm(t.en).toLowerCase();
  if (!normIdx[nk]) { normIdx[nk] = []; }
  normIdx[nk].push(t);
}

const matches = [];
const unmatched = [];
const normOnly = [];
let srcNoEn = 0;
for (const s of srcRows) {
  if (typeof s.en !== 'string' || s.en === '') { srcNoEn++; continue; }
  const hits = exactIdx['E' + s.en] || [];
  if (hits.length === 0) {
    const nh = normIdx['N' + norm(s.en).toLowerCase()] || [];
    if (nh.length) {
      normOnly.push({ rc_project: s.project_name, rc_key: s.key_name, rc_key_id: s.key_id, en: s.en, rc_el: s.el, mt_candidates: nh.length, mt_en: nh[0].en, mt_key: nh[0].key_name, mt_key_id: nh[0].key_id, mt_project: nh[0].project_name, mt_project_id: nh[0].project_id, mt_el: nh[0].el, mt_el_reviewed: nh[0].el_reviewed });
    } else {
      unmatched.push({ rc_project: s.project_name, rc_key: s.key_name, en: s.en });
    }
    continue;
  }
  for (const t of hits) {
    matches.push({
      rc_project: s.project_name,
      rc_key_id: s.key_id,
      rc_key: s.key_name,
      rc_archived: s.is_archived,
      rc_plural: s.is_plural,
      en: s.en,
      rc_el: s.el,
      rc_el_by: s.el_modified_by_email,
      rc_el_at: s.el_modified_at,
      rc_el_reviewed: s.el_reviewed,
      mt_project: t.project_name,
      mt_project_id: t.project_id,
      mt_key_id: t.key_id,
      mt_key: t.key_name,
      mt_archived: t.is_archived,
      mt_plural: t.is_plural,
      mt_translation_id: t.el_translation_id,
      mt_el: t.el,
      mt_el_by: t.el_modified_by_email,
      mt_el_at: t.el_modified_at,
      mt_el_reviewed: t.el_reviewed,
      same_already: s.el === t.el,
      mt_el_empty: (t.el === null || t.el === '')
    });
  }
}

const uniq = {};
for (const m of matches) { uniq[m.rc_key_id] = 1; }

return [{ json: {
  statuses: statuses,
  failed: failed,
  keys_per_project: perProject,
  sample_translation: sampleTrans,
  src_row_count: srcRows.length,
  tgt_row_count: tgtRows.length,
  src_without_en: srcNoEn,
  match_count: matches.length,
  matched_rc_keys: Object.keys(uniq).length,
  unmatched_count: unmatched.length,
  norm_only_count: normOnly.length,
  diag: metas[0] ? metas[0].json.diag_all : null,
  matches: matches,
  norm_only: normOnly,
  unmatched: unmatched
} }];
